import heapq
from collections import Counter


def _dependency_solver(data, preference, name_order):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    versions = {
        name: sorted(row["version"] for row in rows
                     if row["version"] not in blocked.get(name, [])
                     and (name not in pins or row["version"] == pins[name]))
        for name, rows in packages.items()
    }
    rows_by_version = {
        name: {row["version"]: row for row in rows}
        for name, rows in packages.items()
    }
    roots = data["roots"]
    vector_names = names if name_order == "ascending" else list(reversed(names))
    choices = [[-1] + versions[name] for name in names]
    best_vector = None
    best = None

    for values in product(*choices):
        selected = dict(zip(names, values))
        if any(selected.get(name, -1) < bounds[0]
               or selected.get(name, -1) > bounds[1]
               for name, bounds in roots.items()):
            continue
        if any(selected[name] != -1 and selected[name] not in versions[name]
               for name in names):
            continue

        reachable = set()
        edges = {}
        stack = list(roots)
        valid = True
        while stack and valid:
            name = stack.pop()
            if name in reachable:
                continue
            version = selected.get(name, -1)
            if version == -1:
                valid = False
                break
            reachable.add(name)
            deps = []
            row = rows_by_version[name][version]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                value = selected.get(other, -1)
                if value < dep["min"] or value > dep["max"]:
                    valid = False
                    break
                deps.append(other)
                stack.append(other)
            edges[name] = deps

        if not valid or any(value != -1 and name not in reachable
                            for name, value in selected.items()):
            continue

        done, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in done:
                return True
            active.add(name)
            if any(not visit(other) for other in edges.get(name, [])):
                return False
            active.remove(name)
            done.add(name)
            return True

        if not all(visit(name) for name in reachable):
            continue
        vector = tuple(selected[name] for name in vector_names)
        if best_vector is None or (vector < best_vector if preference == "minimum"
                                   else vector > best_vector):
            best_vector = vector
            best = {name: selected[name] for name in names
                    if selected[name] != -1}

    return {"error": "unsatisfiable"} if best is None else {"versions": best}


def _build_dependency_solver(preference, name_order):
    return lambda data: _dependency_solver(data, preference, name_order)


def _component_06(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(n, d):
        if mode == "half_up":
            return (n + d // 2) // d
        return n // d

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(net * event.get("tax_bp", 0), 10000)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_07(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_ids = None
    best_value = None

    for mask in range(1 << len(jobs)):
        chosen = [jobs[i] for i in range(len(jobs)) if mask >> i & 1]
        if len(chosen) != k:
            continue
        ids = {job["id"] for job in chosen}
        if ids & blocked or not mandatory.issubset(ids):
            continue
        counts = Counter(job["group"] for job in chosen)
        if any(not low <= counts[group] <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(chosen, key=lambda job: (job["start"], job["end"], job["id"]))
        if any(ordered[i - 1]["end"] > ordered[i]["start"]
               for i in range(1, len(ordered))):
            continue
        id_list = sorted(ids)
        value = sum(job["value"] for job in chosen)
        if (best_value is None or value > best_value
                or (value == best_value and id_list < best_ids)):
            best_value, best_ids = value, id_list

    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _component_08(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bit.get(source, 0)
    initial = (source, initial_mask, 0)
    distances = {initial: data["start"]}
    queue = [(data["start"], source, initial_mask, 0)]
    coupons = data["coupons"]
    deadline = data["deadline"]

    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full and used == coupons:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            outcomes = [(edge["duration"], used)]
            if used < coupons:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                outcomes.append((duration, used + 1))
            for duration, next_used in outcomes:
                arrival = depart + duration
                if arrival > deadline:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_mask, next_used)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_used))
    return {"arrival": None}


